package net.civeira.phylax.features.document.snippetversion.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.snippetversion.domain.SnippetVersion;
import net.civeira.phylax.features.document.snippetversion.domain.gateway.SnippetVersionCursor;
import net.civeira.phylax.features.document.snippetversion.domain.gateway.SnippetVersionFilter;

class SnippetVersionSlider extends Slider<SnippetVersion> {

  /**
   * @autogenerated SlideGenerator
   */
  private final SnippetVersionCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final SnippetVersionFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<SnippetVersionFilter, SnippetVersionCursor, Iterator<SnippetVersion>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  SnippetVersionSlider(final Iterator<SnippetVersion> multi, final int limit,
      final BiFunction<SnippetVersionFilter, SnippetVersionCursor, Iterator<SnippetVersion>> gateway,
      final SnippetVersionFilter filter, final SnippetVersionCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param snippetVersions
   * @param limit
   * @return
   */
  @Override
  public Iterator<SnippetVersion> next(List<SnippetVersion> snippetVersions, int limit) {
    SnippetVersion last = snippetVersions.get(snippetVersions.size() - 1);
    SnippetVersionCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
